alter table public.staff_accounts add column if not exists login_slug text, add column if not exists primary_branch_id uuid references public.branches(id) on delete set null, add column if not exists settings jsonb not null default '{}'::jsonb, add column if not exists permission_overrides jsonb not null default '{}'::jsonb, add column if not exists department text, add column if not exists job_title text, add column if not exists phone text, add column if not exists email text, add column if not exists avatar_url text, add column if not exists notes text;
create unique index if not exists staff_accounts_login_slug_unique on public.staff_accounts(login_slug) where login_slug is not null;
create index if not exists staff_accounts_primary_branch_idx on public.staff_accounts(store_id, primary_branch_id);
create table if not exists public.staff_branch_access (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, staff_id uuid not null references public.staff_accounts(id) on delete cascade, branch_id uuid not null references public.branches(id) on delete cascade, is_primary boolean not null default false, can_sell boolean not null default true, can_view_reports boolean not null default false, can_manage_inventory boolean not null default false, can_manage_customers boolean not null default false, can_manage_orders boolean not null default false, can_manage_expenses boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(staff_id, branch_id));
create index if not exists staff_branch_access_store_branch_idx on public.staff_branch_access(store_id, branch_id);
create table if not exists public.staff_permission_overrides (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, staff_id uuid not null references public.staff_accounts(id) on delete cascade, permission text not null, allowed boolean not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(staff_id, permission));
create index if not exists staff_permission_overrides_store_staff_idx on public.staff_permission_overrides(store_id, staff_id);
create table if not exists public.staff_settings (staff_id uuid primary key references public.staff_accounts(id) on delete cascade, store_id uuid not null references public.stores(id) on delete cascade, landing_route text not null default '/sell', theme text not null default 'system', compact_mode boolean not null default false, show_prices boolean not null default true, show_stock boolean not null default true, allow_keyboard_shortcuts boolean not null default true, receipt_auto_print boolean not null default false, sound_feedback boolean not null default true, language text not null default 'en', timezone text not null default 'Africa/Lagos', settings jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.staff_login_events (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, staff_id uuid not null references public.staff_accounts(id) on delete cascade, branch_id uuid references public.branches(id) on delete set null, success boolean not null, ip_hash text, user_agent text, created_at timestamptz not null default now());
create index if not exists staff_login_events_staff_created_idx on public.staff_login_events(staff_id, created_at desc);
alter table public.staff_branch_access enable row level security; alter table public.staff_permission_overrides enable row level security; alter table public.staff_settings enable row level security; alter table public.staff_login_events enable row level security;
revoke all on public.staff_branch_access from anon, authenticated; revoke all on public.staff_permission_overrides from anon, authenticated; revoke all on public.staff_settings from anon, authenticated; revoke all on public.staff_login_events from anon, authenticated;
create or replace function public.generate_staff_login_slug(_name text) returns text language plpgsql security definer set search_path=public as $func$ declare base text; candidate text; i integer := 0; begin base := trim(both '-' from regexp_replace(lower(coalesce(_name,'staff')), '[^a-z0-9]+', '-', 'g')); if base='' then base:='staff'; end if; candidate:=base; while exists(select 1 from public.staff_accounts where login_slug=candidate) loop i:=i+1; candidate:=base||'-'||i; end loop; return candidate; end $func$;
create or replace function public.staff_login_url(_slug text) returns text language sql stable security definer set search_path=public as $func$ select '/staff-login/' || trim(both '/' from _slug) $func$;
insert into public.staff_settings(staff_id, store_id) select id, store_id from public.staff_accounts on conflict (staff_id) do nothing;
do $seed$ declare r record; base text; candidate text; n integer; begin for r in select id,name from public.staff_accounts where login_slug is null loop base:=trim(both '-' from regexp_replace(lower(coalesce(r.name,'staff')), '[^a-z0-9]+', '-', 'g')); if base='' then base:='staff'; end if; candidate:=base; n:=0; while exists(select 1 from public.staff_accounts where login_slug=candidate and id<>r.id) loop n:=n+1; candidate:=base||'-'||n; end loop; update public.staff_accounts set login_slug=candidate where id=r.id; end loop; end $seed$;
comment on column public.staff_accounts.login_slug is 'Non-secret dedicated staff sign-in identifier.';
comment on column public.staff_accounts.primary_branch_id is 'Default branch/workspace for this staff member.';
